'use strict';
let data=[],pythonData=[],javaData=[],index=0,problemIndex=0,lang='python',tab='learn',chosen=null,worker=null,timer=null;const passed=new Set(),solved=new Set(),studied=new Set(),drafts={};const $=id=>document.getElementById(id);const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let learnerProfile={displayName:'',goal:'',dailyMinutes:30},cloudConflicts=[],mock=null,mockInterval=null;
window.codeTrailMockActive=()=>!!mock;
const lesson=()=>data[index];const problem=()=>lesson().problem;const key=()=>lesson().id+lang+':'+problemIndex;
function captureState(){return {schemaVersion:1,passed:[...passed],solved:[...solved],studied:[...studied],drafts:{...drafts},conflicts:cloudConflicts,profile:{...learnerProfile},lang,lessonId:lesson()?.id||'py01'}}
function persist(){if(data.length)window.courseSync?.queue(captureState())}
function applyCloud(s,keepNavigation=false){const activeKey=data.length?key():null;const mounted=$('editor');const oldDraft=activeKey?drafts[activeKey]:undefined;const safeToRefresh=keepNavigation&&mounted&&mounted.value===oldDraft;learnerProfile={displayName:'',goal:'',dailyMinutes:30,...(s.profile||{})};for(const [set,values] of [[passed,s.passed],[solved,s.solved],[studied,s.studied]]){set.clear();for(const k of values||[])set.add(k)}for(const k of Object.keys(drafts))delete drafts[k];Object.assign(drafts,s.drafts||{});cloudConflicts=s.conflicts||[];if(safeToRefresh&&Object.hasOwn(drafts,activeKey))mounted.value=drafts[activeKey];if(!keepNavigation){lang=s.lang==='java'?'java':'python';data=lang==='python'?pythonData:javaData;index=Math.max(0,data.findIndex(t=>t.id===s.lessonId));problemIndex=0;$('language').value=lang}renderConflicts();}
function renderConflicts(){$('recovered-drafts').hidden=!cloudConflicts.length;$('conflict-list').replaceChildren();for(const c of cloudConflicts){const d=document.createElement('details'),summary=document.createElement('summary'),pre=document.createElement('pre'),b=document.createElement('button');summary.textContent=c.key+' · '+c.label;pre.textContent=c.code;b.textContent='Restore this version';b.className='secondary';b.onclick=()=>{saveDraft();for(const l of ['python','java']){const rows=l==='python'?pythonData:javaData;const i=rows.findIndex(t=>c.key.startsWith(t.id+l+':'));if(i>=0){stop();stopMock();lang=l;data=rows;index=i;problemIndex=Number(c.key.split(':').pop())||0;$('language').value=lang;drafts[c.key]=c.code;tab='practice';render();persist();$('workspace').scrollIntoView();break}}};d.append(summary,pre,b);$('conflict-list').append(d)}}
function saveDraft(){if($('editor')&&data.length)drafts[key()]=$('editor').value;persist()}
function stop(){if(worker){worker.terminate();worker=null}clearTimeout(timer)}
function stopMock(announce=false){if(!mock)return;mock=null;clearInterval(mockInterval);if(announce)window.alert('Timed practice ended. Review your code and score yourself using the checkpoint rubric.');}
function openTopic(i){if(!Number.isInteger(i)||i<0||i>=data.length)throw Error('Unknown topic');saveDraft();stop();stopMock();index=i;problemIndex=0;tab='learn';chosen=null;$('search').value='';render();persist()}
function switchTab(t){saveDraft();stop();tab=t;chosen=null;render()}
function modules(){return [...new Map(data.map(t=>[t.moduleId||t.level,t.moduleTitle||t.level])).entries()]}
function courseUI(){window.LearnerFeatures?.trackView?.(lang==='python'?'python-dsa':'java-basics');if($('study-together'))$('study-together').href='/community?course='+(lang==='python'?'python-dsa':'java-basics');const count=data.reduce((n,t)=>n+(t.problems?.length||1),0);$('course-stats').innerHTML=`<div><strong>${modules().length}</strong><span>guided modules</span></div><div><strong>${data.length}</strong><span>in-depth lessons</span></div><div><strong>${count}</strong><span>original problems</span></div><div><strong>${[...solved].filter(k=>data.some(l=>k.startsWith(l.id+lang+':'))).length}</strong><span>problem test suites passed</span></div>`;$('module-map').innerHTML=modules().map(([id,title],i)=>`<details class="module-row"><summary><span>${String(i+1).padStart(2,'0')}</span>${esc(title)}</summary><div>${data.map((t,j)=>(t.moduleId||t.level)===id?`<button data-lesson="${j}">${studied.has(t.id)?'✓ ':''}${esc(t.title)}<small>${t.durationMinutes?esc(t.durationMinutes)+' min lesson':'Lesson'} · ${t.problems?.length||1} problems</small></button>`:'').join('')}</div></details>`).join('');document.querySelectorAll('[data-lesson]').forEach(b=>b.onclick=()=>{openTopic(Number(b.dataset.lesson));$('workspace').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'})});$('module-select').innerHTML=modules().map(([id,title],i)=>`<option value="${esc(id)}">${i+1}. ${esc(title)}</option>`).join('');$('module-select').value=lesson().moduleId||lesson().level}
function nav(){const q=$('search').value.toLowerCase(),module=lesson().moduleId||lesson().level;$('topics').innerHTML=data.map((t,i)=>{if(q?!(`${t.title} ${t.summary} ${t.moduleTitle||''}`).toLowerCase().includes(q):(t.moduleId||t.level)!==module)return '';return `<button class="${i===index?'active':''}" data-index="${i}" aria-current="${i===index?'step':'false'}"><span class="num">${studied.has(t.id)?'✓':String(i+1).padStart(2,'0')}</span>${esc(t.title)}</button>`}).join('')||'<p class="empty">No matching lessons.</p>';document.querySelectorAll('[data-index]').forEach(b=>b.onclick=()=>openTopic(Number(b.dataset.index)))}
function codeCard(code,title){return `<div class="code-card"><div class="code-top"><span>${esc(title)}</span><span class="dots" aria-hidden="true">●●●</span></div><pre>${esc(code)}</pre></div>`}
function render(){if(!data.length)return;const t=lesson();t.problem=t.problems?.[problemIndex]||t.problem;const p=problem();courseUI();nav();$('count').textContent=[...passed].filter(k=>data.some(l=>k.startsWith(l.id+':'))).length;$('total').textContent=data.reduce((n,l)=>n+(l.problems?.length||1),0);$('level').textContent=t.level;$('title').textContent=t.title;$('summary').textContent=t.summary;$('step').textContent=`LESSON ${String(index+1).padStart(2,'0')} / ${data.length}`;document.querySelectorAll('[data-tab]').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.tab===tab)));$('next').textContent=index===data.length-1?'Back to first lesson':'Next lesson';
if(tab==='learn'){$('content').innerHTML=`<div class="grid"><article class="card">${t.objectives?`<div class="objectives"><h3>What you’ll be able to do</h3><ul>${t.objectives.map(o=>`<li>${esc(o)}</li>`).join('')}</ul><small>${esc(t.durationMinutes)} minutes suggested for this lesson, plus problem-solving time</small></div>`:''}<h3>The concept, step by step</h3><div class="lesson">${esc(t.lesson)}</div><div class="actions"><button class="primary" id="start">Practice this lesson</button><button class="secondary" id="studied">${studied.has(t.id)?'Marked as studied':'Mark as studied'}</button></div></article><div>${codeCard(t[lang],`${lang==='python'?'Python':'Java'} · worked example`)}<div class="notice">Trace this example by hand. Explain why it works, name an edge case, and predict the output before running it. “Studied” is a bookmark, not a mastery score.</div></div></div>`;$('start').onclick=()=>switchTab('practice');$('studied').onclick=()=>{studied.has(t.id)?studied.delete(t.id):studied.add(t.id);persist();render()}}
if(tab==='practice'||tab==='check'){const picker=t.problems?`<div class="problem-picker">${t.problems.map((x,i)=>`<button class="${i===problemIndex?'selected':''}" data-problem="${i}">${i+1}. ${esc(x.title)} <small>${esc(x.difficulty)}</small></button>`).join('')}</div>`:'';if(tab==='practice'){const starter=p.starter||(lang==='python'?'# Write your solution and print the result.\n':`public class Main {\n    public static void main(String[] args) {\n        // Your solution\n    }\n}\n`);$('content').innerHTML=picker+`<div class="mock-bar"><div><strong>Interview practice</strong><span id="mock-clock">${mock?'Timed practice running':'Explain first. Then code and test.'}</span></div><button class="secondary" id="mock-toggle">${mock?'End timed practice':'Start '+(p.timeMinutes||25)+'-minute no-run mock'}</button></div><div class="grid"><article class="card"><span class="tag">${esc(p.difficulty||'Practice')} · ${esc(p.pattern||t.title)}</span><h3 style="margin-top:16px">${esc(p.title)}</h3><div class="problem">${esc(p.prompt)}</div><div class="examples"><div class="example"><small>EXAMPLE INPUT</small>${esc(p.input)}</div><div class="example"><small>EXPECTED OUTPUT</small>${esc(p.output)}</div></div>${mock?'<p class="notice">Hints, solutions, AI help and code execution are hidden during this practice timer. This is a course exercise, not a real employer assessment.</p>':p.hints.map((h,i)=>`<details><summary>Hint ${i+1}</summary><p>${esc(h)}</p></details>`).join('')+`<details><summary>Solution and complexity</summary><p>${esc(p.explanation)}</p>${p.complexity?`<p><strong>Analysis:</strong> ${esc(p.complexity)}</p>`:''}<pre>${esc(p[lang])}</pre><button class="secondary" id="load-solution">Load worked solution</button></details>`}</article><div><div class="code-card"><div class="code-top"><span>${lang==='python'?'solution.py':'Main.java'}</span><span class="dots">●●●</span></div><textarea id="editor" spellcheck="false" aria-label="${lang} solution code">${esc(drafts[key()]??starter)}</textarea><div class="editor-actions">${lang==='python'?`<button class="primary" id="run" ${mock?'disabled':''}>Run Python</button>${p.tests?`<button class="primary" id="run-tests" ${mock?'disabled':''}>Run ${p.tests.length} tests</button>`:''}<button class="secondary" id="stop">Stop</button>`:'<button class="primary" id="download">Download Main.java</button>'}<button class="secondary" id="copy">Copy code</button></div><div class="editor-note">${lang==='python'?(p.tests?'Implement the solve function exactly as described, then run the tests. Returning a value is different from printing it.':'Assign the sample values and print the result.')+' Python runs on your device. Interactive input() is unsupported.':'Java editor only: download and compile with your JDK.'}</div><button class="secondary" id="explain-console" style="margin:0 18px 14px">Explain this output / error ✦</button><div class="output" id="output" role="status">${p.tests?'The supplied test cases cover examples and edge cases, not every possible input. Passing them is not proof of full correctness.':lang==='python'?'Output appears here.':'Run: javac Main.java\nThen: java Main'}</div></div><div class="notice">After solving: explain your invariant, time complexity, space complexity, and how you would test an unseen input. Record where you needed help.</div></div></div>`;$('explain-console').onclick=()=>window.codeTrailTutor?.explainConsole();$('editor').oninput=saveDraft;$('editor').onkeydown=e=>{if(e.key==='Tab'){e.preventDefault();e.target.setRangeText('    ',e.target.selectionStart,e.target.selectionEnd,'end');saveDraft()}};$('copy').onclick=async()=>{try{await navigator.clipboard.writeText($('editor').value);$('copy').textContent='Copied'}catch{$('output').textContent='Select the code and copy with your keyboard.'}};if($('load-solution'))$('load-solution').onclick=()=>{$('editor').value=p[lang];saveDraft();$('output').textContent='Worked solution loaded. Re-solve a fresh variation without notes to test your understanding.'};if(lang==='python'){$('run').onclick=()=>runPython(false);if($('run-tests'))$('run-tests').onclick=()=>runPython(true);$('stop').onclick=()=>{stop();$('output').textContent='Stopped.';$('run').disabled=!!mock;if($('run-tests'))$('run-tests').disabled=!!mock}}else $('download').onclick=()=>{const u=URL.createObjectURL(new Blob([$('editor').value],{type:'text/plain'})),a=document.createElement('a');a.href=u;a.download='Main.java';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)};$('mock-toggle').onclick=()=>{saveDraft();stop();if(mock){stopMock();render();return}mock={end:Date.now()+(p.timeMinutes||25)*60000};mockInterval=setInterval(()=>{if(!mock)return;const seconds=Math.max(0,Math.ceil((mock.end-Date.now())/1000));if($('mock-clock'))$('mock-clock').textContent=String(Math.floor(seconds/60)).padStart(2,'0')+':'+String(seconds%60).padStart(2,'0')+' remaining';if(seconds===0){saveDraft();stopMock();render();$('output').textContent='Time is up. Review against the checkpoint rubric before using hints or tests.'}},500);render()}}else{$('content').innerHTML=picker+`<article class="card"><span class="tag">Knowledge check</span><h3 class="question">${esc(p.quiz.question)}</h3><div class="choices">${p.quiz.choices.map((c,i)=>`<button class="choice" data-choice="${i}" aria-pressed="false">${String.fromCharCode(65+i)}. ${esc(c)}</button>`).join('')}</div><div class="actions"><button class="primary" id="answer">Check my answer</button></div><div class="feedback" id="feedback" role="status"></div></article>`;document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{chosen=Number(b.dataset.choice);document.querySelectorAll('[data-choice]').forEach(c=>{c.classList.toggle('selected',c===b);c.setAttribute('aria-pressed',String(c===b))});$('feedback').textContent=''});$('answer').onclick=()=>{if(chosen===null){$('feedback').textContent='Choose an answer first.';return}if(chosen===p.quiz.answer){passed.add(t.id+':'+problemIndex);$('feedback').textContent='Correct. '+p.quiz.explanation;persist();$('count').textContent=[...passed].filter(k=>data.some(l=>k.startsWith(l.id+':'))).length}else $('feedback').textContent='Not quite. '+p.quiz.explanation}}document.querySelectorAll('[data-problem]').forEach(b=>b.onclick=()=>{saveDraft();stop();stopMock();problemIndex=Number(b.dataset.problem);chosen=null;render()})}
}
function runPython(withTests=false){if(mock)return;stop();saveDraft();const out=$('output'),run=$('run'),button=$('run-tests'),code=$('editor').value,p=problem(),problemKey=key();run.disabled=true;if(button)button.disabled=true;out.textContent='Loading Python… First run downloads the runtime.';worker=new Worker('python-worker.js',{type:'module'});function enable(){run.disabled=false;if(button)button.disabled=false}timer=setTimeout(()=>{stop();out.textContent='Stopped after 60 seconds. Check for an infinite loop, or retry if the download was slow.';enable()},60000);worker.onmessage=e=>{if(e.data.ready){out.textContent='Running…';return}clearTimeout(timer);enable();const r=e.data;out.textContent=(r.output||'')+(r.error?'\n'+r.error:'');if(r.tests){out.textContent+='\n'+r.tests.map((x,i)=>`${x.passed?'PASS':'FAIL'} ${i+1}: ${x.passed?'OK':x.error||'Expected '+JSON.stringify(x.expected)+'; got '+JSON.stringify(x.actual)}`).join('\n');if(r.tests.length&&r.tests.every(x=>x.passed)){solved.add(problemKey);persist();courseUI();out.textContent+='\n\nAll supplied tests passed. Now justify correctness and complexity.'}}else if(!out.textContent)out.textContent='No printed output. If you implemented solve(), use Run tests to check its return values.';stop()};worker.onerror=()=>{stop();enable();out.textContent='Python could not load. Check your connection and try again.'};worker.postMessage({code,tests:withTests?p.tests:null})}
$('search').oninput=nav;$('module-select').onchange=e=>openTopic(data.findIndex(t=>(t.moduleId||t.level)===e.target.value));$('language').onchange=e=>{saveDraft();stop();stopMock();lang=e.target.value;data=lang==='python'?pythonData:javaData;index=0;problemIndex=0;render();persist()};document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>switchTab(b.dataset.tab));$('next').onclick=()=>openTopic((index+1)%data.length);Promise.all([fetch('course-python.json'),fetch('curriculum.json')].map(async r=>{const x=await r;if(!x.ok)throw Error('Unavailable');return x.json()})).then(async([p,j])=>{pythonData=p;javaData=j;data=p;await window.courseSync.start({capture:captureState,apply:applyCloud,onLoaded:()=>render()});const query=new URLSearchParams(location.search);const requestedLang=query.get('language');const requestedLesson=query.get('lesson');if(requestedLesson){const rows=requestedLang==='java'?javaData:pythonData;const selected=rows.findIndex(x=>x.id===requestedLesson);if(selected>=0){lang=requestedLang==='java'?'java':'python';data=rows;index=selected;$('language').value=lang;const pi=Number(query.get('problem'));if(query.has('problem')&&Number.isInteger(pi)&&pi>=0&&pi<(rows[selected].problems?.length||1)){problemIndex=pi;tab='practice';}persist();}}render();const ctx=document.modelContext;if(ctx?.registerTool)Promise.resolve(ctx.registerTool({name:'open_learning_topic',description:'Open one topic in the current course.',inputSchema:{type:'object',properties:{topicId:{type:'string'}},required:['topicId'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){const i=data.findIndex(t=>t.id===input?.topicId);openTopic(i);return {topicId:data[i].id,title:data[i].title}}})).catch(()=>{})}).catch(()=>{$('content').innerHTML='<div class="card">Could not load the course. Refresh to try again.</div>'});

document.addEventListener('click',async e=>{const a=e.target.closest?.('a[href]');if(!a||e.defaultPrevented||e.button!==0||e.ctrlKey||e.metaKey||e.shiftKey||e.altKey||a.target==='_blank')return;const url=new URL(a.href,location.href);if(url.origin!==location.origin||url.pathname===location.pathname||!window.courseSync?.isConnected()||!data.length)return;e.preventDefault();saveDraft();const ok=await window.courseSync.saveNow();if(ok)location.assign(a.href);else $('save-status').textContent='Your latest changes are not saved yet. Keep this tab open and retry sync before leaving.';});
